/* Leituras cívicas: somente ocorrências reais, aprovadas e públicas. */
(()=>{
'use strict';
const D=window.CidadeConectaData,S=window.CidadeConectaPublicSource,V=window.CidadeConectaCivic,U=window.CidadeConectaUI;
if(!V)return;
const e=V.esc,$=s=>document.querySelector(s),date=d=>D.time(d)===null?'—':new Date(d).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'});
const hasRead=()=>{const s=S.state();return s.status==='live'||s.lastSuccess>0||s.rows.length>0},count=n=>hasRead()?fmt(n):'—';
const route=()=>location.hash.replace(/^#\/?/,'').split('?')[0],fmt=n=>Number(n).toLocaleString('pt-BR');
const selected=(v,k)=>v===k?' selected':'';
const opts=(items,value)=>items.map(([v,label])=>`<option value="${e(v)}"${selected(value,v)}>${e(label)}</option>`).join('');
function filters(q,{compare=false}={}){
 const t=V.territory(),names=D.allNeighborhoods(t),f=Object.fromEntries(q);
 const active=['from','to','category','bairro','region','status'].filter(k=>q.get(k)).length;
 return `<details class="civic-filter-disclosure" ${active?'open':''}><summary>Filtrar dados públicos${active?' · '+active+' ativo(s)':' por período e território'}</summary><form id="civicFilters" class="civic-filters" aria-label="Filtrar dados públicos"><label>Período inicial<input name="from" type="date" value="${e(/^\d{4}-\d\d-\d\d$/.test(f.from)?f.from:'')}"></label><label>Período final<input name="to" type="date" value="${e(/^\d{4}-\d\d-\d\d$/.test(f.to)?f.to:'')}"></label><label>Categoria<select name="category"><option value="">Todas as categorias</option>${opts(Object.entries(D.CATEGORIES),f.category)}</select></label>${compare?'':`<label>Bairro<select name="bairro"><option value="">Todos os bairros</option>${opts(names.map(x=>[x,x]),f.bairro)}</select></label><label>Região<select name="region"><option value="">Todas as regiões</option>${opts((t?.administrativeRegions||[]).map(r=>[String(r.id),'Região '+r.id]),f.region)}</select></label><label>Status<select name="status"><option value="">Todos os status</option>${opts(D.STATUSES.map(x=>[x,x]),f.status)}</select></label>`}<div class="civic-filter-actions"><button class="btn primary" type="submit">Aplicar filtros</button><a class="btn secondary" href="#/${route()}">Limpar filtros</a></div><p id="civicFilterError" class="civic-form-error" role="alert"></p></form></details>`;
}
function filtered(q){return D.filter(D.realRows(S.state().rows),Object.fromEntries(q),V.territory())}
function shell(k,title,description,body,q,{filter=false,compare=false,demo=false,heading=""}={}){
 const source=demo?'<div class="civic-demo-source" role="note"><strong>Modo DEMO · conteúdo totalmente fictício</strong><span>Nomes, números, imagens, notícias e ocorrências desta visão existem apenas para apresentação do projeto.</span></div>':V.sourceLabel();
 const method=demo?'Esta página usa somente conteúdo fictício isolado da base pública. Nada desta demonstração entra em métricas, mapa, exportações ou dados reais do Cidade Conecta.':'Os indicadores consideram apenas registros reais publicados e aprovados. Representam participação na plataforma, sem estimar a incidência total dos problemas na cidade. Os exemplos de demonstração ficam fora deste conjunto.';
 return{title,html:(heading||U.pageHead(k,title,description))+`<section class="section${heading?' civic-news-shell':''}"><div class="wrap civic-public ${demo?'civic-public-demo':''}" id="civicPublicPage"><nav class="civic-subnav" aria-label="Explorar dados da cidade">${[['agora','Cidade Agora'],['resolvidas','Problemas Resolvidos'],['dashboard','Pulso da Cidade'],['feed','Feed'],['noticias','Notícias'],['comparar','Comparar bairros'],['dados-abertos','Dados Abertos'],['relatorios','Relatórios']].map(([p,t])=>`<a href="#/${p}" ${route()===p?'aria-current="page"':''}>${t}</a>`).join('')}</nav>${source}${filter?filters(q,{compare}):''}${body}<p class="small muted civic-method">${method}</p><div class="civic-page-tools">${demo?'<a class="btn secondary" href="#/noticias">Voltar ao jornal real</a>':'<button class="btn secondary" data-civic-refresh>Atualizar leitura</button><button class="btn secondary" data-civic-share-page>Compartilhar esta visão</button><a class="miniLink" href="#/transparencia">Como os dados são protegidos →</a>'}</div></div></section>`,bind:()=>bind(q)};
}
function kpis(m){return `<div class="civic-kpis dashboardKpisV51"><div><b>${count(m.total)}</b><span>Registros no recorte</span></div><div><b>${count(m.open)}</b><span>Abertos</span></div><div><b>${count(m.resolved)}</b><span>Resolvidos</span></div><div><b>${!hasRead()||m.rate===null?'—':m.rate+'%'}</b><span>Proporção resolvida</span></div></div>`}
function bars(items,label,category=false){const demoMode=new URLSearchParams((location.hash.split('?')[1]||'')).get('demo')==='1'||route()==='perfil-demo';if(!hasRead()&&!demoMode)return '<p class="muted">Aguardando uma leitura pública válida para calcular os indicadores.</p>';return items.length?`<ol class="civic-bars" aria-label="${e(label)}">${items.slice(0,8).map(x=>`<li><span>${e(category?D.CATEGORIES[x.label]:x.label)}</span><b>${fmt(x.count)}</b><meter min="0" max="${Math.max(...items.map(x=>x.count),1)}" value="${x.count}">${x.count}</meter></li>`).join('')}</ol>`:'<p class="muted">Sem registros públicos neste recorte.</p>'}
function events(rows,limit=12){const a=D.feed(rows,limit);return a.length?`<ol class="civic-feed">${a.map(x=>`<li><span class="civic-feed-dot" aria-hidden="true"></span><div><span class="miniLabel">${e(date(x.date))} · ${e(x.protocol)}</span><h3><a href="#/ocorrencia/${e(x.protocol)}">${e(x.type==='created'?'Nova ocorrência pública em '+x.bairro:D.CATEGORIES[x.category]+' · '+x.bairro+' passou para '+x.status)}</a></h3><p>${e(x.title)}</p></div>${V.badge(x.status)}</li>`).join('')}</ol>`:V.empty('Ainda não há atualizações públicas neste recorte','Quando ocorrências forem aprovadas e receberem atualizações, elas aparecerão aqui. Nenhum dado de contato é mostrado.','<div class="civic-empty-actions"><a class="btn primary" href="#/registrar">Registrar problema</a><a class="btn secondary" href="#/mapa">Abrir mapa</a></div>')}
function recent(rows){return rows.filter(o=>o.status==='Resolvida').sort((a,b)=>(D.time(b.resolved)||D.lastUpdate(b))-(D.time(a.resolved)||D.lastUpdate(a))).filter(o=>(D.time(o.resolved)||D.time(o.history.find(h=>h.status==='Resolvida')?.date)||0)>=Date.now()-30*D.DAY)}
function newsVisual(category,label='',media=null){
 const cat=Object.hasOwn(D.CATEGORIES,category)?category:'outros',name=D.CATEGORIES[cat]||'Cidade';
 if(media?.url){const demo=media.demo===true;return `<figure class="civic-news-cover civic-news-cover-real civic-news-cover--${e(cat)} ${demo?'civic-news-cover-demo':''}"><img src="${e(media.url)}" alt="${e(media.alt||((demo?'Ilustração de demonstração de ':'Imagem pública moderada de ')+name+(label?' em '+label:'')))}" loading="lazy" decoding="async" referrerpolicy="no-referrer" data-civic-public-photo><figcaption><span>${demo?'Imagem ilustrativa · DEMO':'Imagem pública moderada'}</span><strong>${e(name)}</strong>${label?`<small>${e(label)}</small>`:''}${mediaCredit(media)}</figcaption></figure>`}
 return `<figure class="civic-news-cover civic-news-cover--${e(cat)}" aria-label="Capa editorial de ${e(name)}"><svg viewBox="0 0 640 360" role="img" aria-hidden="true" focusable="false"><rect width="640" height="360" rx="24" fill="currentColor" opacity=".09"/><circle cx="530" cy="76" r="46" fill="currentColor" opacity=".08"/><path d="M0 285 95 220l63 42 78-112 86 88 86-74 82 82 70-60 80 64v110H0Z" fill="currentColor" opacity=".09"/><path d="M70 278h500M108 278v-98h66v98m36 0V130h78v148m42 0v-72h64v72m42 0V102h82v176" fill="none" stroke="currentColor" stroke-width="10" stroke-linecap="round" stroke-linejoin="round" opacity=".24"/><path d="M95 122h80M105 150h60M224 168h50M452 142h48" stroke="currentColor" stroke-width="8" stroke-linecap="round" opacity=".2"/></svg><figcaption><span>Capa editorial</span><strong>${e(name)}</strong>${label?`<small>${e(label)}</small>`:''}</figcaption></figure>`;
}
function newsHeadline(x){return x.type==='resolved'?'Problema resolvido em '+x.bairro:x.type==='created'?'Novo registro público em '+x.bairro:D.CATEGORIES[x.category]+' em '+x.bairro+' mudou para '+x.status}
function newsType(x){return x.type==='resolved'?'resolvidas':x.type==='created'?'novos':'atualizacoes'}
function cityNewsSection(){
 const City=window.CidadeConectaCityNews;if(!City)return '';
 const agenda=City.agenda||[],gallery=City.gallery||[];
 const photo=(item,cls='')=>`<figure class="civic-city-photo ${cls}"><img data-civic-city-photo src="${e(item.image.url)}" alt="${e(item.image.alt||item.title||'Piracicaba')}" loading="lazy" decoding="async" referrerpolicy="no-referrer"><div class="civic-city-photo-fallback" aria-hidden="true"><span>Piracicaba</span><small>Visual de apoio do Cidade Conecta</small></div><figcaption><b>${e(item.title||item.image.alt||'Piracicaba')}</b>${item.subtitle?`<span>${e(item.subtitle)}</span>`:''}<small class="civic-city-photo-credit">Foto: <a href="${e(item.image.source)}" target="_blank" rel="noopener noreferrer">${e(item.image.credit)}</a> · ${e(item.image.license)}</small><small class="civic-city-photo-fallback-note">Visual local de apoio · crédito acima se refere à foto original.</small></figcaption></figure>`;
 return `<section class="civic-city-news" aria-labelledby="cityAgendaTitle">
  <div class="civic-news-section-head civic-city-news-head"><div><span class="miniLabel">Agenda real da cidade</span><h2 id="cityAgendaTitle">Acontece em Piracicaba</h2><p>Eventos e atividades locais reunidos de fontes públicas. Confirme programação, inscrições e alterações no link de origem.</p></div><a class="btn secondary smallBtn" href="${e(City.agendaSource)}" target="_blank" rel="noopener noreferrer">Ver agenda de origem ↗</a></div>
  <div class="civic-city-agenda-grid">${agenda.map(item=>`<article class="civic-city-agenda-card">${photo(item,'civic-city-agenda-photo')}<div class="civic-city-agenda-copy"><div class="civic-city-date"><b>${e(item.dateLabel)}</b><span>${e(item.time)}</span></div><span class="miniLabel">${e(item.category)}</span><h3>${e(item.title)}</h3><p>${e(item.summary)}</p><div class="civic-city-agenda-meta"><span>${e(item.place)}</span><small>Fonte: ${e(item.sourceLabel)}</small></div><a class="miniLink" href="${e(item.url)}" target="_blank" rel="noopener noreferrer">Ver informações na fonte →</a></div></article>`).join('')}</div>
  <div class="civic-news-section-head civic-city-gallery-head"><div><span class="miniLabel">Piracicaba em imagens</span><h2>Uma cidade que também conta histórias pela paisagem</h2><p>Fotografias reais da cidade com crédito e licença aberta, usadas para dar contexto visual ao jornal.</p></div><span class="miniLabel">${e(City.updatedLabel)}</span></div>
  <div class="civic-city-gallery">${gallery.map(item=>photo(item,'civic-city-gallery-photo')).join('')}</div>
 </section>`;
}
function mediaCredit(media){
 if(!media?.real)return '';
 return `<small class="civic-demo-photo-credit"><b>Foto real ilustrativa</b> · não representa a ocorrência fictícia. <a href="${e(media.source)}" target="_blank" rel="noopener noreferrer">${e(media.credit)}</a> · ${e(media.license)}</small><small class="civic-demo-fallback-credit">Visual local de apoio · a foto original não foi exibida nesta sessão.</small>`;
}
function beforeAfter(o){
 if(o?.status!=='Resolvida')return '';
 const images=[
  {media:o.media,label:'Antes',caption:'Registro inicial moderado',alt:'Imagem pública anterior à resolução'},
  {media:o.resolutionMedia,label:'Depois',caption:'Resultado publicado',alt:'Imagem pública após a resolução'}
 ].filter(x=>x.media?.url);
 if(!images.length)return '';
 const comparison=images.length===2,title=comparison?'Antes e depois':'Imagem pública da ocorrência';
 return `<section class="civic-before-after" aria-label="${title}"><div class="civic-news-section-head"><h3>${title}</h3><span class="miniLabel">Mídia moderada</span></div><div class="civic-before-after-grid${comparison?'':' is-single'}">${images.map(x=>`<figure><img src="${e(x.media.url)}" alt="${e(x.media.alt||x.alt)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" data-civic-public-photo><figcaption><b>${x.label}</b><span>${x.caption}</span></figcaption></figure>`).join('')}</div>${comparison?'<p class="small muted">As duas imagens pertencem ao mesmo protocolo.</p>':''}</section>`;
}
function editorialCover(post){
 if(post?.cover?.url)return `<figure class="civic-news-cover civic-news-cover-real"><img src="${e(post.cover.url)}" alt="${e(post.cover.alt||('Imagem pública moderada da matéria '+post.title))}" loading="lazy" decoding="async" referrerpolicy="no-referrer" data-civic-public-photo><figcaption><span>Matéria editorial</span><strong>${e(post.category||'Cidade Conecta')}</strong></figcaption></figure>`;
 return newsVisual('outros','Matéria editorial');
}
function editorialDetail(post){
 const paragraphs=String(post.body||'').split(/\n{2,}/).map(x=>x.trim()).filter(Boolean);
 return `<article class="civic-news-article civic-editorial-article"><a class="miniLink" href="#/noticias">← Voltar ao jornal</a><header><span class="miniLabel">Editorial · ${e(post.category||'Cidade Conecta')}</span><h2>${e(post.title)}</h2><p class="civic-news-deck">${e(post.summary||'Atualização editorial do Cidade Conecta.')}</p><div class="civic-news-byline">${e(date(post.publishedAt||post.updatedAt))} · Cidade Conecta</div></header>${editorialCover(post)}<div class="civic-editorial-body">${paragraphs.length?paragraphs.map(p=>`<p>${e(p)}</p>`).join(''):`<p>${e(post.summary||'')}</p>`}</div><div class="actions"><button class="btn secondary" data-civic-share-page type="button">Compartilhar matéria</button>${post.coverProtocol?`<a class="btn soft" href="#/ocorrencia/${e(post.coverProtocol)}">Ver ocorrência relacionada</a>`:''}</div><p class="small muted">Conteúdo editorial publicado pelo painel administrativo. Quando há imagem, ela vem exclusivamente de mídia pública moderada.</p></article>`;
}
function editorialSection(posts){
 if(!posts.length)return '';
 const featured=posts.find(x=>x.featured)||posts[0],others=posts.filter(x=>x.id!==featured.id).slice(0,5);
 return `<section class="civic-editorial-section"><div class="civic-news-section-head"><h2>Em destaque</h2><span class="miniLabel">Publicação editorial</span></div><div class="civic-editorial-grid"><article class="civic-editorial-feature">${editorialCover(featured)}<div><span class="miniLabel">${e(featured.category||'Cidade Conecta')}</span><h2><a href="#/noticias?materia=${e(featured.slug)}">${e(featured.title)}</a></h2><p>${e(featured.summary)}</p><a class="miniLink" href="#/noticias?materia=${e(featured.slug)}">Ler matéria completa →</a></div></article><div class="civic-editorial-briefs">${others.map(p=>`<article><span class="miniLabel">${e(date(p.publishedAt||p.updatedAt))}</span><h3><a href="#/noticias?materia=${e(p.slug)}">${e(p.title)}</a></h3><p>${e(p.summary)}</p></article>`).join('')}</div></div></section>`;
}

function newsDetail(protocol,rows,demo=false){
 const o=rows.find(x=>x.protocol===protocol);if(!o)return null;
 const when=o.resolved||o.history.find(h=>h.status==='Resolvida')?.date||o.updated||o.created,regions=D.regionsFor(o.bairro,V.territory()).map(r=>'Região '+r).join(' · '),media=o.demoImage||o.media;
 const history=(o.history||[]).slice().sort((a,b)=>D.time(b.date)-D.time(a.date));
 return `<article class="civic-news-article ${demo?'civic-demo-article':''}"><a class="miniLink" href="#/noticias${demo?'?demo=1':''}">← Voltar ao jornal</a>${demo?'<span class="civic-demo-stamp">DEMO · MATÉRIA FICTÍCIA</span>':''}<header><span class="miniLabel">${e(D.CATEGORIES[o.category])} · ${e(o.status)}</span><h2>${e(o.title)}</h2><p class="civic-news-deck">${e(o.description||'Atualização vinculada a esta ocorrência.')}</p><div class="civic-news-byline">${e(date(when))} · ${e(o.bairro||'Bairro não informado')} ${regions?'· '+e(regions):''} · ${e(o.protocol)}</div></header>${newsVisual(o.category,o.bairro,media)}${demo?'':beforeAfter(o)}<div class="civic-news-article-grid"><section><h3>O que consta no registro</h3><p>${e(o.description||'Sem descrição adicional.')}</p><h3>Histórico ${demo?'fictício':'público'}</h3>${history.length?`<ol class="civic-news-timeline">${history.map(h=>`<li><time>${e(date(h.date))}</time><div><b>${e(h.status)}</b>${h.note?`<p>${e(h.note)}</p>`:''}</div></li>`).join('')}</ol>`:V.empty('Sem histórico adicional','A ocorrência ainda não possui eventos além do estado atual.')}</section><aside><div class="civic-news-facts"><span><b>Status</b>${e(o.status)}</span><span><b>Bairro</b>${e(o.bairro||'Não informado')}</span><span><b>Categoria</b>${e(D.CATEGORIES[o.category])}</span><span><b>Referência responsável</b>${e(o.agency||'Não informada')}</span></div>${demo?'<a class="btn primary" href="#/perfil-demo">Ver perfil fictício</a>':`<a class="btn primary" href="#/ocorrencia/${e(o.protocol)}">Abrir ocorrência</a><button class="btn secondary" data-civic-share-page type="button">Compartilhar esta notícia</button>`}</aside></div><p class="small muted">${demo?(media?.real?'A fotografia é real e licenciada, mas é usada apenas como ilustração. A ocorrência, o protocolo, o histórico e a notícia são totalmente fictícios.':'Imagem e conteúdo ilustrativos de demonstração. Não representam fato real.'):o.media?.url?'A imagem acima é uma cópia pública moderada vinculada a esta ocorrência.':'A imagem acima é uma capa editorial ilustrada por categoria e não uma fotografia do local.'}</p></article>`;
}
function trend(rows,days){const c=D.compare(rows,days,Date.now(),S.state().complete&&!S.state().cached);return `<article class="card civic-trend"><span class="miniLabel">Tendência de registros · períodos de ${c.days} dias</span><h2>${c.eligible?(c.change===0?'Volume estável':(c.change>0?'Aumento de ':'Redução de ')+Math.abs(c.change)+'%'):'Base insuficiente para afirmar uma tendência'}</h2><p>${c.eligible?'A comparação mede o volume de registros na plataforma. Não identifica a causa da variação.':e(c.reason)}</p><div class="civic-period-pair"><div><b>${count(c.current)}</b><span>Atual · ${date(c.currentStart)} a ${date(c.currentEnd)}</span></div><div><b>${count(c.previous)}</b><span>Anterior · ${date(c.previousStart)} a ${date(c.previousEnd)} (limite final exclusivo)</span></div></div></article>`}
function city(q){const rows=filtered(q),m=D.metrics(rows),last=recent(rows).slice(0,3);return shell('Participação em movimento','Cidade Agora','Um retrato do que foi publicado na plataforma, com contexto e sem números de demonstração.',`<div class="civic-city-lead"><div><span class="miniLabel">Leitura da cidade</span><h2>Informação pública que ajuda a acompanhar o cotidiano.</h2><p class="muted">Veja novos relatos, acompanhe atualizações e encontre o Radar do seu bairro.</p><a class="btn primary" href="#/mapa">Explorar o mapa</a><a class="btn secondary" href="#/bairro">Radar dos bairros</a></div><div class="civic-today"><b>${count(m.today)}</b><span>novos registros hoje</span><small>Horário de Piracicaba · base pública</small></div></div>${kpis(m)}<div class="civic-two-col"><article class="card"><h2>Últimas atualizações</h2>${events(rows,6)}<a class="miniLink" href="#/feed">Abrir feed da cidade →</a></article><article class="card"><h2>Onde a participação acontece</h2>${bars(m.bairros,'Bairros com registros')}<a class="miniLink" href="#/comparar">Comparar bairros com contexto →</a><h3>Categorias em destaque</h3>${bars(m.categories,'Categorias mais registradas',true)}</article></div><div class="titleRow"><h2>Resolvidas recentemente</h2><a class="miniLink" href="#/resolvidas">Ver todas →</a></div>${last.length?`<div class="civic-records">${last.map(o=>V.card(o)).join('')}</div>`:V.empty('Ainda não há resoluções públicas recentes','Esta área reúne registros com resolução datada nos últimos 30 dias.')}`,q,{filter:true})}
function pulse(q){if(q.get('demo')==='1')return null;const rows=filtered(q),m=D.metrics(rows),all=D.realRows(S.state().rows),days=[7,30,90].includes(Number(q.get('days')))?Number(q.get('days')):30,t=D.observedTimes(rows),now=D.metrics(all),trendRows=D.filter(all,{category:q.get('category'),bairro:q.get('bairro'),region:q.get('region')},V.territory());return shell('Dados com contexto','Pulso da Cidade','Indicadores calculados a partir da leitura pública. Compare períodos equivalentes e conheça a base de cada número.',`${kpis(m)}<div class="civic-window-summary"><span><b>${count(now.today)}</b> novos hoje</span><span><b>${count(now.days7)}</b> nos últimos 7 dias</span><span><b>${count(now.days30)}</b> nos últimos 30 dias</span><small>Contagens de entrada de toda a base pública, independentemente dos filtros do recorte.</small></div><div class="civic-two-col"><article class="card"><h2>Situação no recorte</h2>${bars(D.STATUSES.map(label=>({label,count:m.statuses[label]})),'Status dos registros')}</article><article class="card"><h2>Categorias mais frequentes</h2>${bars(m.categories,'Categorias',true)}</article></div><div class="civic-period-switch" aria-label="Período de comparação">${[7,30,90].map(n=>{const p=new URLSearchParams(q);p.set('days',n);return `<a class="btn ${n===days?'primary':'secondary'}" href="#/dashboard?${e(p.toString())}" ${n===days?'aria-current="true"':''}>${n} dias</a>`}).join('')}</div><p class="small muted">A tendência usa janelas móveis completas até hoje, mantendo categoria, bairro e região. Datas e status do recorte não alteram essas janelas.</p>${trend(trendRows,days)}<article class="card"><span class="miniLabel">Histórico público</span><h2>Tempo de atendimento observado</h2><p class="muted">Mediana entre a criação e o primeiro evento de cada tipo no histórico público disponível. Não é SLA oficial nem promessa de prazo. Eventos privados e registros sem datas válidas não entram no cálculo.</p><div class="civic-observed">${[['first','Até a primeira atualização'],['forwarded','Até o encaminhamento'],['started','Até o início'],['resolved','Até a resolução']].map(([key,label])=>`<div><span>${label}</span><b>${t[key].hours===null?'—':t[key].hours<24?Math.round(t[key].hours*10)/10+' h':Math.round(t[key].hours/24*10)/10+(Math.round(t[key].hours/24*10)/10===1?' dia':' dias')}</b><small>Base: ${t[key].n} registro(s)</small></div>`).join('')}</div></article><article class="card"><h2>Registros por região</h2>${bars((V.territory()?.administrativeRegions||[]).map(r=>({label:'Região '+r.id,count:rows.filter(o=>D.regionsFor(o.bairro,V.territory()).includes(Number(r.id))).length})),'Registros reais por região')}<p class="small muted">Usa os vínculos existentes de bairro e região. Um bairro com mais de um vínculo pode contar em duas regiões; os totais regionais não devem ser somados como pessoas ou ocorrências únicas.</p><h2>Bairros mais ativos na plataforma</h2>${bars(m.bairros,'Bairros')}<p class="small muted">Mais registros não significam um bairro melhor ou pior. População, acesso digital e participação influenciam esta leitura.</p></article>`,q,{filter:true})}
function feed(q){return shell('O que está mudando','Feed da Cidade','Novos registros e mudanças de status com histórico público. Nenhum nome de cidadão ou dado de contato.',events(filtered(q),60),q,{filter:true})}
function news(q){
 const Demo=window.CidadeConectaDemo,demo=q.get('demo')==='1'&&Demo,News=window.CidadeConectaNewsSource,editorial=demo?[]:(News?.state?.().posts||[]),articleSlug=q.get('materia');
 const rows=demo?Demo.filter(q):filtered(q),protocol=q.get('protocolo');
 if(articleSlug&&!demo){const post=editorial.find(x=>x.slug===articleSlug);return shell('Publicação editorial','Notícias',post?.title||'Matéria editorial',post?editorialDetail(post):V.empty('Matéria não encontrada','Esta publicação não está disponível ou deixou de ser pública.'),q,{filter:false})}
 const validProtocol=demo?/^DEMO-\d{4}-\d{5}$/.test(protocol||''):D.validProtocol(protocol||'');
 if(protocol&&validProtocol){
  const detail=newsDetail(protocol,rows,Boolean(demo));
  return shell(demo?'Demonstração editorial':'Noticiário cívico',demo?'Notícias · DEMO':'Notícias',demo?'Leitura fictícia para apresentação visual do Cidade Conecta.':'Leitura editorial de uma atualização pública do Cidade Conecta.',detail||V.empty('Notícia não encontrada','O protocolo não está disponível nesta leitura.'),q,{filter:false,demo:Boolean(demo)});
 }
 const allItems=demo?Demo.feed(rows,40):D.feed(rows,40),type=['todas','resolvidas','novos','atualizacoes'].includes(q.get('tipo'))?q.get('tipo'):'todas',items=type==='todas'?allItems:allItems.filter(x=>newsType(x)===type),m=demo?Demo.metrics(rows):D.metrics(rows),resolvedRows=rows.filter(o=>o.status==='Resolvida').sort((a,b)=>(D.time(b.resolved)||D.lastUpdate(b))-(D.time(a.resolved)||D.lastUpdate(a))).slice(0,4),lead=items[0]||null;
 const now=new Date(),n=v=>demo?fmt(v):count(v);
 const today=new Intl.DateTimeFormat('pt-BR',{dateStyle:'full',timeZone:'America/Sao_Paulo'}).format(now);
 const calendarDay=new Intl.DateTimeFormat('sv-SE',{dateStyle:'short',timeZone:'America/Sao_Paulo'}).format(now);
 const heading=`<header class="wrap civic-news-masthead"><div><span class="civic-news-kicker">Cidade Conecta Piracicaba ${demo?'· DEMO':''}</span><h1>${demo?'Jornal Demonstrativo':'Notícias da Cidade'}</h1><p>${demo?'Uma edição inteiramente fictícia para conhecer o jornal.':'Ocorrências aprovadas, resoluções e publicações editoriais do Cidade Conecta.'}</p></div><time datetime="${calendarDay}">${e(today)}</time></header>`;
 const href=protocol=>`#/noticias?${demo?'demo=1&':''}protocolo=${e(protocol)}`;
 const tab=(key,label)=>{const p=new URLSearchParams(q);if(demo)p.set('demo','1');if(key==='todas')p.delete('tipo');else p.set('tipo',key);p.delete('protocolo');return `<a href="#/noticias?${e(p.toString())}" ${type===key?'aria-current="page"':''}>${e(label)}</a>`};
 const leadHtml=lead?`<article class="civic-news-lead">${newsVisual(lead.category,lead.bairro,lead.media)}<div class="civic-news-lead-copy">${demo?'<span class="civic-demo-stamp">DEMO</span>':''}<span class="miniLabel">${e(lead.type==='resolved'?'Resolução publicada':lead.type==='created'?'Novo registro':'Atualização de status')}</span><h2><a href="${href(lead.protocol)}">${e(newsHeadline(lead))}</a></h2><p>${e(lead.title)}</p><div class="civic-news-byline">${e(date(lead.date))} · ${e(D.CATEGORIES[lead.category])} · ${e(lead.protocol)}</div><a class="miniLink" href="${href(lead.protocol)}">Ler a notícia →</a></div></article>`:`<article class="civic-news-lead civic-news-empty-lead">${newsVisual('outros','Piracicaba')}${V.empty('Sem manchete no momento',hasRead()?'Quando houver atualizações aprovadas neste recorte, elas aparecerão aqui.':'A leitura de ocorrências públicas está indisponível neste momento.')}</article>`;
 const latest=[...new Map(items.slice().reverse().map(item=>[item.protocol,item])).values()].sort((a,b)=>D.time(b.date)-D.time(a.date)).filter(item=>item.protocol!==lead?.protocol).slice(0,8);
 const latestHtml=latest.length?`<div class="civic-news-list">${latest.map(x=>`<article>${newsVisual(x.category,x.bairro,x.media)}<div class="civic-news-card-copy">${demo?'<span class="civic-demo-chip">DEMO</span>':''}<span class="miniLabel">${e(date(x.date))}</span><h3><a href="${href(x.protocol)}">${e(newsHeadline(x))}</a></h3><p>${e(x.title)}</p><small>${e(D.CATEGORIES[x.category])} · ${e(x.protocol)}</small></div></article>`).join('')}</div>`:V.empty('Sem outras atualizações','Os próximos registros aprovados aparecerão nesta seção.');
 const resolvedHtml=resolvedRows.length?`<div class="civic-news-resolved">${resolvedRows.map(o=>`<article>${newsVisual(o.category,o.bairro,o.demoImage||o.media)}<div>${demo?'<span class="civic-demo-chip">DEMO</span>':''}<span class="miniLabel">Problema resolvido</span><h3><a href="${href(o.protocol)}">${e(o.title)}</a></h3><p>${e(D.CATEGORIES[o.category])} · ${e(o.bairro)}</p></div></article>`).join('')}</div>`:V.empty('Ainda não há problemas resolvidos','As resoluções aparecerão aqui quando existirem no recorte.');
 const profile=demo?`<section class="civic-demo-profile-strip"><div class="civic-demo-avatar">${e(Demo.profile.initials)}</div><div><span class="miniLabel">Perfil fictício que alimenta a apresentação</span><h2>${e(Demo.profile.name)} <small>${e(Demo.profile.handle)}</small></h2><p>${e(Demo.profile.bio)}</p><a class="miniLink" href="#/perfil-demo">Abrir perfil DEMO completo →</a></div></section>`:'';
 const editorialHtml=demo?'':editorialSection(editorial);
 const demoStoriesHtml=demo&&Demo.stories?.length?`<section class="civic-demo-stories"><div class="civic-news-section-head"><div><span class="miniLabel">Caderno de apresentação</span><h2>Mais notícias DEMO</h2></div><span class="miniLabel">${Demo.stories.length} matérias fictícias</span></div><div class="civic-demo-story-grid">${Demo.stories.map(s=>`<article class="civic-demo-story">${newsVisual('outros','Piracicaba',s.photo)}<div><span class="civic-demo-chip">DEMO</span><span class="miniLabel">${e(s.kicker)}</span><h3><a href="${e(s.href)}">${e(s.title)}</a></h3><p>${e(s.summary)}</p><a class="miniLink" href="${e(s.href)}">Explorar esta pauta →</a></div></article>`).join('')}</div></section>`:'';

 const body=`${demo?'<div class="civic-demo-hero-alert"><b>APRESENTAÇÃO FICTÍCIA</b><span>Todos os fatos, protocolos e números desta versão são fictícios. Algumas fotografias são reais, licenciadas e usadas somente como ilustração, sem relação com os acontecimentos simulados.</span></div>':''}
 ${profile}
 <aside class="civic-news-core-note"><div><span class="miniLabel">Núcleo do projeto</span><b>Primeiro, acompanhe o que aconteceu com os problemas urbanos.</b><p>O jornal organiza registros, mudanças de status e resoluções. Agenda e conteúdo da cidade aparecem depois como complemento editorial.</p></div><div class="civic-news-core-actions"><a href="#/registrar">Registrar problema</a><a href="#/mapa">Ver mapa</a><a href="#/resolvidas">Ver resolvidos</a></div></aside>
 <nav class="civic-news-tabs" aria-label="Seções do jornal">${tab('todas','Destaques')}${tab('novos','Novos registros')}${tab('atualizacoes','Atualizações')}${tab('resolvidas','Resolvidos')}</nav>
 <div class="civic-news-rule" aria-hidden="true"></div>
 <section class="civic-news-grid" aria-label="Destaques do noticiário">${leadHtml}<aside class="civic-news-brief"><span class="miniLabel">${demo?'Números fictícios':'Cidade em números'}</span><div><b>${n(m.today)}</b><span>novos hoje</span></div><div><b>${n(m.open)}</b><span>em aberto</span></div><div><b>${n(m.resolved)}</b><span>resolvidos no recorte</span></div>${demo?'<a class="miniLink" href="#/perfil-demo">Conhecer o perfil DEMO →</a>':'<a class="miniLink" href="#/dashboard">Abrir Pulso da Cidade →</a>'}</aside></section>
 <section class="civic-news-section"><div class="civic-news-section-head"><h2>Últimas da cidade</h2>${demo?'<a href="#/perfil-demo">Perfil da demonstração →</a>':'<a href="#/feed">Ver feed completo →</a>'}</div>${latestHtml}</section>
 <section class="civic-news-split"><div><div class="civic-news-section-head"><h2>Resolvidos</h2>${demo?'<a href="#/noticias?demo=1&tipo=resolvidas">Filtrar resolvidos →</a>':'<a href="#/resolvidas">Ver todos →</a>'}</div>${resolvedHtml}</div><aside class="civic-news-sidebar"><section><h2>Bairros em pauta</h2>${bars(m.bairros.slice(0,6),'Bairros com registros')}</section><section><h2>Temas em pauta</h2>${bars(m.categories.slice(0,6),'Categorias com registros',true)}</section></aside></section>
 ${demo?demoStoriesHtml:editorialHtml}
 ${demo?'':cityNewsSection()}
 <aside class="civic-news-note"><strong>${demo?'Sobre esta demonstração':'Sobre este jornal'}</strong><p>${demo?'Conteúdo propositalmente fictício e isolado da base real. Fotografias reais aparecem apenas como ambientação visual, com crédito e licença; elas não documentam nem comprovam as ocorrências simuladas.':'Quando existe uma imagem pública moderada, ela é exibida e identificada como tal. Na ausência de foto aprovada, usamos uma capa editorial ilustrada por categoria. O noticiário usa apenas ocorrências públicas, aprovadas e seus históricos; não é um veículo oficial da Prefeitura e não publica dados privados.'}</p></aside>
 ${demo?'<div class="civic-demo-exit"><a class="btn primary" href="#/noticias">Sair da demonstração e abrir notícias reais</a></div>':'<div class="civic-demo-entry"><div><span class="miniLabel">Quer apresentar o projeto com conteúdo completo?</span><h3>Abra a edição fictícia de demonstração</h3><p class="muted">Perfil, imagens e várias notícias sem misturar nada com a base real.</p></div><a class="btn secondary" href="#/noticias?demo=1">Ver modo DEMO</a></div>'}`;
 return shell(demo?'Edição fictícia':'Noticiário cívico',demo?'Notícias · DEMO':'Notícias',demo?'Jornal fictício completo para apresentar a jornada de ocorrências do produto.':'Acompanhe registros, mudanças de status, resoluções e, em segundo plano, informações locais de Piracicaba.',body,q,{filter:!demo,demo:Boolean(demo),heading})
}
function demoProfile(q){
 const Demo=window.CidadeConectaDemo;if(!Demo)return shell('Demonstração','Perfil DEMO','Conteúdo demonstrativo indisponível.',V.empty('Demonstração indisponível','O pacote fictício não foi carregado.'),q,{demo:true});
 const p=Demo.profile,rows=Demo.rows,m=Demo.metrics(rows),activity=Demo.feed(rows,12),account=Demo.account||{},photos=Object.values(Demo.photos||{});
 const body=`<div class="civic-demo-hero-alert"><b>PERFIL 100% FICTÍCIO</b><span>Este perfil e toda a atividade abaixo existem somente para apresentação do Cidade Conecta.</span></div><section class="civic-demo-profile"><div class="civic-demo-profile-head"><div class="civic-demo-avatar civic-demo-avatar-large">${e(p.initials)}</div><div><span class="miniLabel">${e(p.role)}</span><h2>${e(p.name)} <small>${e(p.handle)}</small></h2><p>${e(p.bio)}</p><div class="civic-demo-badges">${p.badges.map(x=>`<span>${e(x)}</span>`).join('')}</div></div><a class="btn primary" href="#/noticias?demo=1">Abrir jornal DEMO</a></div><div class="civic-kpis"><div><b>${fmt(rows.length)}</b><span>registros fictícios</span></div><div><b>${fmt(m.resolved)}</b><span>resolvidos fictícios</span></div><div><b>${fmt(p.following)}</b><span>acompanhamentos</span></div><div><b>${fmt(p.neighborhoods.length)}</b><span>bairros favoritos</span></div></div></section>
 <section class="civic-demo-profile-grid"><article class="card"><h2>Bairros acompanhados</h2><div class="civic-demo-neighborhoods">${p.neighborhoods.map(x=>`<span>${e(x)}</span>`).join('')}</div><p class="muted">Preferências fictícias usadas para demonstrar personalização.</p></article><article class="card"><h2>Temas mais acompanhados</h2>${bars(m.categories.slice(0,5),'Categorias fictícias',true)}</article></section>
 <section class="civic-demo-profile-grid civic-demo-account-stats"><article class="card"><span class="miniLabel">Conta DEMO preenchida</span><h2>Histórico pessoal para apresentar</h2><div class="civic-mini-metrics"><span><b>${account.created?.length||0}</b> criadas</span><span><b>${account.saved?.length||0}</b> salvas</span><span><b>${account.follows?.length||0}</b> acompanhadas</span><span><b>${account.notifications?.length||0}</b> notificações</span></div><a class="btn secondary smallBtn" href="#/minhas">Abrir Meu Cidade Conecta</a></article><article class="card"><span class="miniLabel">Fotografias da apresentação</span><h2>Imagens reais, fatos fictícios</h2><p class="muted">As fotos abaixo são de Piracicaba e possuem licença aberta. Elas servem apenas para ambientar o modo DEMO.</p><div class="civic-demo-photo-sources">${photos.slice(0,7).map(photo=>`<a href="${e(photo.source)}" target="_blank" rel="noopener noreferrer"><b>${e(photo.credit)}</b><span>${e(photo.license)}</span></a>`).join('')}</div></article></section>
 <section class="civic-news-section"><div class="civic-news-section-head"><h2>Atividade recente do perfil</h2><a href="#/noticias?demo=1">Ver no jornal →</a></div><div class="civic-demo-activity">${activity.map(x=>`<article><span class="civic-demo-chip">DEMO</span><time>${e(date(x.date))}</time><h3><a href="#/noticias?demo=1&protocolo=${e(x.protocol)}">${e(newsHeadline(x))}</a></h3><p>${e(x.title)}</p></article>`).join('')}</div></section>
 <aside class="civic-news-note"><strong>Por que este perfil existe?</strong><p>Ele permite apresentar recursos de personalização, jornal, acompanhamento e histórico mesmo quando a base pública real ainda é pequena. Nenhum item é enviado ao Supabase ou usado em indicadores reais.</p></aside>`;
 return shell('Demonstração segura','Perfil DEMO','Um perfil fictício completo para apresentar personalização, atividade e notícias sem misturar dados reais.',body,q,{demo:true})
}
function resolved(q){
 const rows=filtered(q).filter(o=>o.status==='Resolvida').sort((a,b)=>(D.time(b.resolved)||D.lastUpdate(b))-(D.time(a.resolved)||D.lastUpdate(a)));
 const now=Date.now(),resolvedAt=o=>D.time(o.resolved)||D.time(o.history.find(h=>h.status==='Resolvida')?.date),last7=rows.filter(o=>resolvedAt(o)&&resolvedAt(o)>=now-7*D.DAY).length,last30=rows.filter(o=>resolvedAt(o)&&resolvedAt(o)>=now-30*D.DAY).length,times=D.observedTimes(rows).resolved;
 const median=times.hours===null?'—':times.hours<24?Math.round(times.hours*10)/10+' h':Math.round(times.hours/24*10)/10+' dias';
 const resolvedMetrics=D.metrics(rows),topCategories=resolvedMetrics.categories.slice(0,5),topNeighborhoods=resolvedMetrics.bairros.slice(0,5);
 const body=`<div class="civic-resolved-hero"><div><span class="miniLabel">Transparência de resultados</span><h2>Problemas com resolução publicada</h2><p class="muted">Esta página reúne ocorrências reais e aprovadas que chegaram ao status Resolvida. O histórico continua disponível para conferência.</p><div class="civic-resolved-actions"><a class="btn primary" href="#/mapa?status=Resolvida">Ver resolvidos no mapa</a><a class="btn secondary" href="#/feed?status=Resolvida">Ver atualizações</a></div></div><div class="civic-resolved-seal" aria-hidden="true">✓</div></div>
 <div class="civic-kpis"><div><b>${count(rows.length)}</b><span>Resolvidos no recorte</span></div><div><b>${count(last7)}</b><span>Resolvidos em 7 dias</span></div><div><b>${count(last30)}</b><span>Resolvidos em 30 dias</span></div><div><b>${hasRead()?median:'—'}</b><span>Tempo mediano observado</span></div></div>
 <section class="civic-resolved-contextV90"><article class="card"><span class="miniLabel">Onde aparecem os resultados</span><h3>Categorias com mais resoluções no recorte</h3>${bars(topCategories,'Categorias resolvidas',true)}</article><article class="card"><span class="miniLabel">Território</span><h3>Bairros com resoluções publicadas</h3>${bars(topNeighborhoods,'Bairros com resoluções')}</article></section>
 <aside class="civic-resolved-methodV90"><b>Como ler esta página</b><span>Ela mostra somente registros aprovados que chegaram a “Resolvida”. Tempos são observados no histórico disponível e não representam prazo oficial de atendimento.</span></aside>
 ${rows.length?`<div class="civic-records civic-resolved-list">${rows.map(o=>{const t=D.observedTimes([o]).resolved,hours=t.hours,when=o.resolved||o.history.find(h=>h.status==='Resolvida')?.date,regions=D.regionsFor(o.bairro,V.territory()).map(r=>'Região '+r).join(' · ');return `<article class="civic-resolved-item">${V.card(o,{follow:false})}${beforeAfter(o)}<div class="civic-resolved-meta"><span><b>Registro</b>${e(date(o.created))}</span><span><b>Resolução</b>${e(date(when))}</span><span><b>Tempo observado</b>${hours===null?'Histórico insuficiente':hours<24?Math.round(hours*10)/10+' h':Math.round(hours/24*10)/10+' dias'}</span><span><b>Território</b>${e(regions||o.bairro||'Não informado')}</span><span><b>Referência responsável</b>${e(o.agency||'Não informada')}</span></div><div class="civic-resolved-links"><a class="miniLink" href="#/ocorrencia/${e(o.protocol)}">Ver histórico completo →</a></div></article>`}).join('')}</div>`:V.empty(hasRead()?'Nenhum problema resolvido neste recorte':'Leitura pública indisponível',hasRead()?'Quando uma ocorrência aprovada chegar ao status Resolvida, ela aparecerá aqui.':'Tente atualizar a leitura para consultar as resoluções publicadas.')}`;
 return shell('Resultados publicados','Problemas Resolvidos','Acompanhe ocorrências concluídas, datas de resolução e tempos observados com base no histórico público.',body,q,{filter:true})
}
function compare(q){const names=D.allNeighborhoods(V.territory()),chosen=[...new Set(q.getAll('hood').filter(x=>names.includes(x)))].slice(0,3),rows=filtered(q);return shell('Territórios com contexto','Comparar bairros','Escolha dois ou três bairros. A comparação mostra participação na plataforma e não classifica a qualidade de um território.',`<form id="civicCompare" class="card"><h2>Escolha os bairros</h2><div class="civic-compare-pickers">${[0,1,2].map((n)=>`<label>Bairro ${n+1}${n===2?' (opcional)':''}<select name="hood" ${n<2?'required':''}><option value="">Selecionar bairro</option>${opts(names.map(x=>[x,x]),chosen[n])}</select></label>`).join('')}</div><button class="btn primary" type="submit">Comparar</button><p class="civic-form-error" id="civicCompareError" role="alert"></p></form>${chosen.length>=2?`<div class="civic-comparison" style="--compare-columns:${chosen.length}">${chosen.map(name=>{const a=D.filter(rows,{bairro:name}),m=D.metrics(a);return `<article class="card"><span class="miniLabel">${D.regionsFor(name,V.territory()).map(r=>'Região '+r).join(' · ')||'Núcleo territorial'}</span><h2>${e(name)}</h2><p><b>${m.total}</b> registros · <b>${m.open}</b> abertos · <b>${m.resolved}</b> resolvidos</p>${bars(m.categories,'Categorias de '+name,true)}${trend(a,30)}<a href="#/bairro?nome=${encodeURIComponent(name)}">Abrir Radar →</a></article>`}).join('')}</div>`:V.empty('Selecione pelo menos dois bairros','Os nomes são os da base territorial existente. Nenhum limite ou polígono novo é criado.')}`,q,{filter:true,compare:true})}
const fields=[['protocolo','Código público do registro.'],['titulo','Título público, limitado e com proteção de padrões de contato.'],['categoria','Categoria pública.'],['bairro','Nome da base territorial do projeto.'],['regioes','Vínculos administrativos existentes; pode haver mais de um.'],['status','Situação publicada no instante da leitura.'],['setor','Área de referência informada no registro. Não implica despacho oficial.'],['criado_em','Data de criação em ISO 8601.'],['atualizado_em','Última atualização pública disponível.'],['resolvido_em','Data de resolução, quando disponível.'],['latitude_publica / longitude_publica','Ponto público aproximado com até três casas decimais; nunca o ponto privado.']];
function table(rows,limit=20){const a=D.exportRows(rows,V.territory());return a.length?`<div class="civic-table-scroll" role="region" aria-label="Registros públicos" tabindex="0"><table class="civic-table"><caption>${a.length} registros no recorte · exibindo até ${limit}</caption><thead><tr><th scope="col">Protocolo</th><th scope="col">Título</th><th scope="col">Bairro</th><th scope="col">Categoria</th><th scope="col">Status</th></tr></thead><tbody>${a.slice(0,limit).map(o=>`<tr><th scope="row"><a href="#/ocorrencia/${e(o.protocolo)}">${e(o.protocolo)}</a></th><td>${e(o.titulo)}</td><td>${e(o.bairro)}</td><td>${e(o.categoria)}</td><td>${e(o.status)}</td></tr>`).join('')}</tbody></table></div>`:V.empty('Nenhum registro público para exportar','Uma exportação vazia contém os campos documentados e nenhuma ocorrência de demonstração.')}
function openData(q){const rows=filtered(q);return shell('Transparência na prática','Dados Abertos','Consulte e exporte apenas os campos públicos necessários. Os filtros do arquivo são os mesmos da visão abaixo.',`<article class="card"><div class="titleRow"><div><h2>Conjunto público de ocorrências</h2><p class="muted">${rows.length} registros selecionados. A leitura é limitada a 5.000 registros por consulta; conjuntos parciais são identificados.</p></div><div class="actions"><button class="btn primary" data-civic-export="csv" ${hasRead()?'':'disabled'}>Baixar CSV</button><button class="btn secondary" data-civic-export="json" ${hasRead()?'':'disabled'}>Baixar JSON</button></div></div>${table(rows)}<p class="small muted">Exportação sem contato, endereço privado, identidade Auth, código de acompanhamento ou identificadores internos. CSV em UTF-8 separado por ponto e vírgula; textos que poderiam executar fórmulas são neutralizados.</p></article><article class="card"><h2>Dicionário de campos</h2><dl class="civic-dictionary">${fields.map(([k,v])=>`<div><dt><code>${k}</code></dt><dd>${v}</dd></div>`).join('')}</dl></article>`,q,{filter:true})}
function reports(q){const rows=filtered(q),m=D.metrics(rows),title=q.get('bairro')?'Radar de '+q.get('bairro'):q.get('category')?D.CATEGORIES[q.get('category')]||'Resumo público':'Cidade Conecta — resumo público';return shell('Leituras para compartilhar','Relatórios públicos','Gere um resumo do recorte selecionado. A impressão permite salvar em PDF pelo navegador.',`<article class="card civic-report" id="civicReport"><span class="miniLabel">Cidade Conecta Piracicaba · ${date(new Date().toISOString())}</span><h2>${e(title)}</h2><p>Período: ${q.get('from')?e(date(q.get('from')+'T12:00:00-03:00')):'início da base disponível'} a ${q.get('to')?e(date(q.get('to')+'T12:00:00-03:00')):'data da consulta'}.</p>${kpis(m)}<div class="civic-two-col"><section><h3>Categorias</h3>${bars(m.categories,'Categorias do relatório',true)}</section><section><h3>Situação</h3>${bars(D.STATUSES.map(label=>({label,count:m.statuses[label]})),'Situação do relatório')}</section></div>${table(rows,50)}<p class="small muted">Base: ${rows.length} registros reais aprovados. ${S.state().complete&&!S.state().cached?'Leitura completa no instante da consulta.':'Leitura parcial ou em cache; não extrapolar para o total da cidade.'} Os dados refletem participação, sem aferir a incidência total dos problemas.</p></article><div class="actions civic-report-actions"><button class="btn primary" data-civic-print>Imprimir / salvar PDF</button><button class="btn secondary" data-civic-export="report">Baixar relatório HTML</button><button class="btn secondary" data-civic-export="csv">Baixar dados do recorte</button></div>`,q,{filter:true})}
function demoCenter(q){
 const Demo=window.CidadeConectaDemo,a=Demo?.account,p=Demo?.profile,rows=Demo?.rows||[],m=Demo?.metrics(rows)||{resolved:0};
 const steps=[
  ['1','Mostrar o registro','Comece explicando como o cidadão registra um problema urbano e recebe um protocolo.','#/registrar'],
  ['2','Mostrar o acompanhamento','Apresente protocolo, histórico e etapas publicadas do atendimento.','#/acompanhar'],
  ['3','Abrir o mapa e resultados','Mostre ocorrências no território e depois problemas que chegaram ao status resolvido.','#/mapa'],
  ['4','Mostrar a conta DEMO','Apresente ocorrências criadas, acompanhamentos, bairros, notificações e perfil fictício.','#/minhas'],
  ['5','Encerrar com jornal e transparência','Use o jornal como complemento visual e finalize explicando privacidade e dados públicos.','#/noticias?demo=1']
 ];
 const body=`<section class="civic-demo-presentation-hero"><div><span class="civic-demo-stamp">MODO APRESENTAÇÃO</span><span class="miniLabel">Cidade Conecta Piracicaba</span><h2>Uma demonstração guiada do produto</h2><p>Use este roteiro para apresentar a experiência completa sem depender de dados pessoais ou de ocorrências reais. Tudo que estiver marcado como DEMO é fictício e isolado.</p><div class="actions"><a class="btn primary" href="#/registrar">Começar pelo registro</a><a class="btn secondary" href="#/conta">Entrar na conta DEMO</a></div></div><div class="civic-demo-presentation-score"><span>Conteúdo fictício</span><b>${rows.length}</b><small>ocorrências demonstrativas</small><b>${m.resolved}</b><small>resolvidas</small><b>${a?.notifications?.length||0}</b><small>notificações</small></div></section>
 <section class="civic-demo-tour"><div class="civic-news-section-head"><div><span class="miniLabel">Roteiro sugerido</span><h2>Apresente em cinco etapas</h2></div></div><div class="civic-demo-tour-grid">${steps.map(([n,t,d,h])=>`<article><span>${n}</span><h3>${e(t)}</h3><p>${e(d)}</p><a class="miniLink" href="${h}">Abrir etapa →</a></article>`).join('')}</div></section>
 <section class="civic-demo-presentation-grid"><article class="card"><span class="miniLabel">Perfil usado na demonstração</span><h2>${e(p?.name||'Gabriel Demo')}</h2><p>${e(p?.bio||'Perfil fictício')}</p><div class="civic-demo-badges">${(p?.badges||[]).map(x=>`<span>${e(x)}</span>`).join('')}</div></article><article class="card"><span class="miniLabel">O que vale destacar</span><h2>Recursos já integrados</h2><ul class="civic-demo-feature-list"><li>Conta cidadã opcional e isolada do Admin</li><li>Jornal cívico com versão real e DEMO</li><li>Problemas resolvidos e antes/depois moderado</li><li>Notificações, bairros e acompanhamentos</li><li>Admin operacional com auditoria</li><li>PWA, privacidade, acessibilidade e responsividade</li></ul></article></section>
 <aside class="civic-news-note"><strong>Segurança da demonstração</strong><p>A conta DEMO não cria usuário no Supabase, não grava ocorrências, não altera indicadores reais e pode ser resetada a qualquer momento. Ela existe apenas para apresentação e teste da experiência.</p></aside>`;
 return shell('Apresentação segura','Central DEMO','Roteiro guiado para apresentar o Cidade Conecta sem misturar dados reais e fictícios.',body,q,{demo:true})
}
function transparency(q){
 const rows=filtered(q),m=D.metrics(rows),active=m.statuses['Em andamento'];
 const dates=rows.map(o=>D.time(o.created)).filter(t=>t!==null);
 const period=dates.length?date(Math.min(...dates))+' a '+date(Math.max(...dates)):'Sem datas no recorte disponível';
 const overview=`<section class="card civic-transparency-overview" aria-labelledby="transparencyOverview"><span class="miniLabel">Base pública do Cidade Conecta</span><h2 id="transparencyOverview">O que a leitura pública mostra</h2>
 <div class="civic-kpis">${[[m.total,'Registros aprovados'],[m.resolved,'Resolvidos'],[active,'Em andamento'],[m.bairros.length,'Bairros com registros'],[m.categories.length,'Categorias registradas']].map(([value,label])=>`<div><b>${count(value)}</b><span>${label}</span></div>`).join('')}</div>
 <p class="muted"><b>Período de criação dos registros</b> · ${e(period)}. Os números se referem à participação nesta plataforma e à leitura pública disponível.</p><a class="btn secondary" href="#/dados-abertos">Consultar dados abertos</a></section>`;
 return shell('Confiança por princípio','Centro de Transparência','Entenda o que é publicado, o que permanece privado e como um registro percorre a plataforma.',`${overview}<div class="civic-two-col civic-privacy-cards">${[['Localização enviada','Privada','O ponto exato informado no registro fica em armazenamento privado, protegido pelas permissões do backend.'],['Localização no mapa','Aproximada','O mapa público usa somente latitude e longitude públicas, arredondadas. O endereço privado não aparece.'],['Contato','Privado','Telefone e e-mail não entram no mapa, feed, busca, notificações ou exportações públicas.'],['Dados públicos','Limitados ao necessário','Protocolo, título, descrição moderada, categoria, bairro, situação e atualizações explicitamente públicas.']].map(([t,b,p])=>`<article class="card"><span class="badge">${b}</span><h2>${t}</h2><p>${p}</p></article>`).join('')}</div><article class="card"><h2>O caminho de um registro</h2><ol class="civic-process">${[['Registrar','O cidadão descreve o problema e recebe protocolo e código privado.'],['Validar','A entrada é conferida antes da publicação. Um relato pendente não alimenta a leitura pública.'],['Classificar','Categoria e referência territorial ajudam a organizar a informação.'],['Encaminhar','A área de referência orienta o atendimento; esta plataforma independente não afirma despacho oficial.'],['Atualizar','Apenas notas marcadas como públicas podem aparecer no acompanhamento público.'],['Resolver','A conclusão registrada permite observar tempos e pedir retorno ao cidadão.']].map(([a,b])=>`<li><h3>${a}</h3><p>${b}</p></li>`).join('')}</ol></article><article class="card"><h2>Moderação e histórico</h2><p>Somente registros aprovados e marcados como visíveis são lidos nas áreas públicas. Notas internas, contato, localização privada e dados de autenticação permanecem fora desta leitura. A conta interna precisa de autorização validada no servidor.</p><p>O protocolo não substitui o código privado de acompanhamento. Links compartilhados nunca incluem esse código.</p><a class="miniLink" href="#/privacidade">Ler os princípios de privacidade →</a></article><article class="card"><h2>O que os indicadores podem dizer</h2><p>Volume de registros mede participação na plataforma. Comparações exigem períodos equivalentes e base mínima. Tempos observados usam a mediana do histórico disponível, sem caracterizar SLA oficial.</p><p>Se a conexão falhar, a interface identifica o último conteúdo público em cache. Nenhum envio offline é apresentado como entregue.</p></article>`,q)}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(q){
 document.querySelectorAll('img[data-civic-city-photo]').forEach(image=>{
  const unavailable=()=>{const figure=image.closest('.civic-city-photo');if(figure)figure.classList.add('is-fallback');image.hidden=true};
  if(image.complete&&image.naturalWidth===0)unavailable();else image.addEventListener('error',unavailable,{once:true});
 });
  document.querySelectorAll('img[data-civic-public-photo]').forEach(image=>{
  const unavailable=()=>{const figure=image.closest('.civic-news-cover');if(figure)figure.classList.add('is-fallback');image.hidden=true};
  if(image.complete&&image.naturalWidth===0)unavailable();
  else image.addEventListener('error',unavailable,{once:true});
 });

 $('#civicFilters')?.addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget),a=f.get('from'),b=f.get('to');if(a&&b&&a>b){$('#civicFilterError').textContent='A data final precisa ser igual ou posterior à inicial.';return}const n=new URLSearchParams();for(const [k,v]of f)if(v)n.set(k,v);if(q.get('demo')==='1')n.set('demo','1');for(const name of ['hood','days'])for(const v of q.getAll(name))n.append(name,v);location.hash='#/'+route()+(n.size?'?'+n:'')});
 $('#civicCompare')?.addEventListener('submit',event=>{event.preventDefault();const names=[...new Set(new FormData(event.currentTarget).getAll('hood').filter(Boolean))];if(names.length<2){$('#civicCompareError').textContent='Escolha pelo menos dois bairros diferentes.';return}const n=new URLSearchParams(q);n.delete('hood');names.forEach(x=>n.append('hood',x));location.hash='#/comparar?'+n});
 document.querySelectorAll('[data-civic-export]').forEach(b=>b.onclick=()=>{const rows=filtered(q),a=D.exportRows(rows,V.territory()),kind=b.dataset.civicExport;if(kind==='csv')download('cidade-conecta-dados-publicos.csv',D.csv(a),'text/csv;charset=utf-8');else if(kind==='json')download('cidade-conecta-dados-publicos.json',JSON.stringify({generatedAt:new Date().toISOString(),source:'public-approved',complete:S.state().complete&&!S.state().cached,filters:Object.fromEntries([...q].filter(([k,v])=>['from','to'].includes(k)?/^\d{4}-\d\d-\d\d$/.test(v):k==='category'?Object.hasOwn(D.CATEGORIES,v):k==='bairro'?D.allNeighborhoods(V.territory()).includes(v):k==='region'?/^[1-9]$/.test(v):k==='status'?D.STATUSES.includes(v):false)),occurrences:a},null,2),'application/json');else{const html=$('#civicReport').outerHTML;download('cidade-conecta-relatorio.html','<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Relatório público · Cidade Conecta</title><style>body{font:16px/1.6 system-ui;max-width:1000px;margin:32px auto;padding:20px;color:#103c3e}table{border-collapse:collapse;width:100%}td,th{padding:10px;border:1px solid #ccd8d1;text-align:left}a{color:#125d60}.civic-kpis{display:flex;flex-wrap:wrap;gap:24px}.civic-kpis b{display:block;font-size:28px}.civic-kpis span{display:block}meter{display:none}.miniLabel,.muted{color:#536863}</style><body>'+html+'<p>Fonte: leitura pública do Cidade Conecta Piracicaba. Sem dados privados.</p></body></html>','text/html;charset=utf-8')}});
 $('[data-civic-print]')?.addEventListener('click',()=>window.print());
 $('[data-civic-share-page]')?.addEventListener('click',()=>{if(window.CidadeConectaShare)window.CidadeConectaShare.open();else navigator.clipboard?.writeText(location.origin+location.pathname+location.hash).then(()=>U.toast('Link público copiado.')).catch(()=>U.toast('Copie o endereço desta visão no navegador.'))});
}
for(const [name,renderer]of Object.entries({agora:city,noticias:news,'perfil-demo':demoProfile,demonstracao:demoCenter,dashboard:pulse,feed,resolvidas:resolved,comparar:compare,'dados-abertos':openData,relatorios:reports,transparencia:transparency}))V.register(name,renderer);
})();
